const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * The oldest retirement that still holds its slug at `now`. A retirement made
 * exactly `ORG_SLUG_HOLD_DAYS` ago has been released, hence the strict `>`
 * against this cutoff wherever it is used.
 */
function holdCutoff(now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

/**
 * Resolves a URL slug to its workspace: the current slug first, then a slug the
 * workspace retired inside the hold period. Every slug-to-workspace lookup goes
 * through here, so the session layer and the organization services agree.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const live = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (live) return toOrganization(live);

  const retired = getDb()
    .select({ org: organizations })
    .from(organizationSlugHistory)
    .innerJoin(organizations, eq(organizations.id, organizationSlugHistory.orgId))
    .where(
      and(
        eq(organizationSlugHistory.slug, slug),
        gt(organizationSlugHistory.retiredAt, holdCutoff(new Date())),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return retired ? toOrganization(retired.org) : null;
}

