/**
 * Moves `orgId` to `slug` and retires the slug it gives up, in one transaction.
 * Returns `null`, changing nothing, when another workspace holds `slug`: as a
 * current slug, live or deleted, or as a retirement still inside the hold.
 *
 * Renaming back to a slug this workspace retired ends that retirement. Every
 * other earlier slug keeps the hold it was given.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization | null> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);
    if (current.slug === slug) return toOrganization(current);

    const cutoff = holdCutoff(new Date());
    const heldAsCurrent = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
      .get();
    const heldAsRetired = tx
      .select({ id: organizationSlugHistory.id })
      .from(organizationSlugHistory)
      .where(
        and(
          eq(organizationSlugHistory.slug, slug),
          ne(organizationSlugHistory.orgId, orgId),
          gt(organizationSlugHistory.retiredAt, cutoff),
        ),
      )
      .get();
    if (heldAsCurrent || heldAsRetired) return null;

    const stamp = toIsoTimestamp(new Date());
    tx.delete(organizationSlugHistory)
      .where(
        and(
          eq(organizationSlugHistory.orgId, orgId),
          eq(organizationSlugHistory.slug, slug),
        ),
      )
      .run();
    tx.insert(organizationSlugHistory)
      .values({ id: newId(), orgId, slug: current.slug, retiredAt: stamp })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
    return toOrganization(row);
  });
}

/**
 * Feeds `uniqueSlug()`: every current slug and every retired slug still held,
 * under `prefix`. Creation suffixes around both, so a held slug is never reused
 * by derivation. Matching on the prefix keeps the scan small.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const current = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const retired = getDb()
    .select({ slug: organizationSlugHistory.slug })
    .from(organizationSlugHistory)
    .where(
      and(
        like(organizationSlugHistory.slug, `${prefix}%`),
        gt(organizationSlugHistory.retiredAt, holdCutoff(new Date())),
      ),
    )
    .all();
  return [...current, ...retired].map((row) => row.slug);
}

