/**
 * Workspace URL renames (ADR 0005): the new slug is current everywhere, the old
 * one is held for `ORG_SLUG_HOLD_DAYS`, and a rename publishes and audits once.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import * as orgRepo from "@/server/repositories/organization-repository";
import { listActivity } from "@/server/services/activity-service";
import * as orgService from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import { toIsoTimestamp } from "@/types/common";
import type { Tenant } from "../server/_support/fixtures";
import type { UserId } from "@/types/common";
import type { TaskflowEventMap } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

function rename(tenant: Tenant, slug: string) {
  return orgService.renameOrganizationSlug(tenant.actors.owner, {
    orgId: tenant.org.id,
    slug,
  });
}

function principalFor(userId: UserId): SessionPrincipal {
  return {
    userId,
    email: "owner@example.test",
    activeOrgId: null,
    expiresAt: toIsoTimestamp(new Date(Date.now() + DAY_MS)),
  };
}

describe("renameOrganizationSlug", () => {
  it("makes the new slug the current one wherever the slug is read", async () => {
    const tenant = await createTenant("current-old", "growth");

    const renamed = await rename(tenant, "current-new");
    expect(renamed.slug).toBe("current-new");
    expect(renamed.name).toBe(tenant.org.name);
    expect(renamed.plan).toBe(tenant.org.plan);
    expect(renamed.settings).toEqual(tenant.org.settings);

    const summary = await orgService.getOrganizationSummary(
      tenant.actors.member,
      tenant.org.id,
    );
    expect(summary.organization.slug).toBe("current-new");

    const listed = await orgService.listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.slug).toBe("current-new");

    const actor = await resolveActorForOrg(
      principalFor(tenant.userIds.owner),
      "current-new",
    );
    expect(actor).toMatchObject({ orgId: tenant.org.id, role: "owner" });
  });

  it("keeps the old slug resolving to the workspace during the hold", async () => {
    const tenant = await createTenant("hold-old", "growth");
    await rename(tenant, "hold-new");

    expect((await orgRepo.findOrgBySlug("hold-old"))?.id).toBe(tenant.org.id);

    const actor = await resolveActorForOrg(
      principalFor(tenant.userIds.member),
      "hold-old",
    );
    expect(actor).toMatchObject({ orgId: tenant.org.id, role: "member" });
  });

  it("releases the old slug exactly ORG_SLUG_HOLD_DAYS after the rename", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    const renamedAt = new Date("2026-10-09T00:00:00.000Z");
    vi.setSystemTime(renamedAt);

    const tenant = await createTenant("release-old", "growth");
    await rename(tenant, "release-new");

    vi.setSystemTime(new Date(renamedAt.getTime() + ORG_SLUG_HOLD_DAYS * DAY_MS - 1));
    expect((await orgRepo.findOrgBySlug("release-old"))?.id).toBe(tenant.org.id);

    vi.setSystemTime(new Date(renamedAt.getTime() + ORG_SLUG_HOLD_DAYS * DAY_MS));
    expect(await orgRepo.findOrgBySlug("release-old")).toBeNull();

    const other = await createTenant("release-other", "growth");
    const taken = await rename(other, "release-old");
    expect(taken.slug).toBe("release-old");
  });

  it("refuses a slug another workspace holds, current or retired, and changes nothing", async () => {
    const holder = await createTenant("refuse-holder", "growth");
    await rename(holder, "refuse-holder-next");
    const other = await createTenant("refuse-other", "growth");

    await expect(rename(other, "refuse-holder")).rejects.toBeInstanceOf(
      InvalidSlugError,
    );
    await expect(rename(other, "refuse-holder-next")).rejects.toBeInstanceOf(
      InvalidSlugError,
    );

    expect((await orgRepo.findOrgById(other.org.id))?.slug).toBe("refuse-other");
    expect((await orgRepo.findOrgBySlug("refuse-holder"))?.id).toBe(holder.org.id);
  });

  it("refuses a slug held by a deleted workspace", async () => {
    const deleted = await createTenant("deleted-holder", "growth");
    await orgRepo.archiveOrg(deleted.org.id);
    const other = await createTenant("deleted-other", "growth");

    await expect(rename(other, "deleted-holder")).rejects.toBeInstanceOf(
      InvalidSlugError,
    );
  });

  it("refuses a malformed or reserved slug", async () => {
    const tenant = await createTenant("shape-old", "growth");

    await expect(rename(tenant, "Not Valid")).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(rename(tenant, "settings")).rejects.toBeInstanceOf(InvalidSlugError);
    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("shape-old");
  });

  it("lets the workspace take back a slug it retired, even inside the hold", async () => {
    const tenant = await createTenant("chain-a", "growth");
    await rename(tenant, "chain-b");
    await rename(tenant, "chain-c");

    expect((await orgRepo.findOrgBySlug("chain-a"))?.id).toBe(tenant.org.id);
    expect((await orgRepo.findOrgBySlug("chain-b"))?.id).toBe(tenant.org.id);

    const back = await rename(tenant, "chain-a");
    expect(back.slug).toBe("chain-a");
    expect((await orgRepo.findOrgBySlug("chain-c"))?.id).toBe(tenant.org.id);
    expect((await orgRepo.findOrgBySlug("chain-b"))?.id).toBe(tenant.org.id);
  });

  it("is a no-op for the current slug: nothing changes, nothing is published or audited", async () => {
    const tenant = await createTenant("noop-same", "growth");
    const seen: TaskflowEventMap["organization.slug_changed"][] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });

    const result = await rename(tenant, "noop-same");
    off();

    expect(result.slug).toBe("noop-same");
    expect(result.updatedAt).toBe(tenant.org.updatedAt);
    expect(seen).toHaveLength(0);

    const audit = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(audit.total).toBe(0);
  });

  it("publishes once and audits once, naming both slugs and the actor", async () => {
    const tenant = await createTenant("announce-old", "growth");
    const seen: TaskflowEventMap["organization.slug_changed"][] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });

    await orgService.renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "announce-new",
    });
    off();

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "announce-old",
      to: "announce-new",
    });

    const page = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "announce-old", to: "announce-new" },
    });
  });

  it("refuses a rename by a member, and the refusal changes nothing", async () => {
    const tenant = await createTenant("perm-old", "growth");

    await expect(
      orgService.renameOrganizationSlug(tenant.actors.member, {
        orgId: tenant.org.id,
        slug: "perm-new",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("perm-old");
  });

  it("makes creation derive around a slug that is still held", async () => {
    const tenant = await createTenant("created-held", "growth");
    await rename(tenant, "created-held-next");

    const created = await orgService.createOrganization(tenant.userIds.owner, {
      name: "Created Held",
      slug: "created-held",
      plan: "free",
    });

    expect(created.slug).toBe("created-held-2");
  });
});

