    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "announce-old", to: "announce-new" },
    });
  });

  it("refuses a rename by a member, and the refusal changes nothing", async () => {
    const tenant = await createTenant("perm-old", "growth");

    await expect(
      orgService.renameOrganizationSlug(tenant.actors.member, {
